const events=[{p:1,date:{de:'01. MAI',en:'01 MAY'},de:['SOHBAT & Get Together','Vergangene Veranstaltung · 1. Mai · Schaflandstraße 11/1, Fellbach.'],en:['SOHBAT & Get Together','Past event · 1 May · Schaflandstraße 11/1, Fellbach.']},{p:0,date:{de:'25. APR',en:'25 APR'},de:['Hadsch & Umrah Seminar','Vergangene Veranstaltung · 25. April · KNIEID e.V.'],en:['Hajj & Umrah seminar','Past event · 25 April · KNIEID e.V.']},{p:0,date:{de:'20. MÄR',en:'20 MAR'},de:['Eid-ul-Fitr-Gebet','Vergangene Veranstaltung · 20. März · KNIEID e.V.'],en:['Eid-ul-Fitr prayer','Past event · 20 March · KNIEID e.V.']},{p:0,date:{de:'08. MÄR',en:'08 MAR'},de:['Iftar und Khatam-e-Quran','Vergangene Veranstaltung · 8. März · Schaflandstraße 11/1, Fellbach.'],en:['Iftar and Khatam-e-Quran','Past event · 8 March · Schaflandstraße 11/1, Fellbach.']}];
Object.assign(copy.de,{brandline:'KULTUR & DIVERSITÄT · FELLBACH',eyebrow:'IN FELLBACH VERWURZELT. MITEINANDER VERBUNDEN.',intro:'KNIEID e.V. ist der Verein zur Förderung von Kultur, Netzwerk, Integration, Entwicklung, Inspiration und Diversität. In Fellbach im Raum Stuttgart schaffen wir Begegnung – mit einem besonderen Blick auf muslimisches Leben und einem offenen Herzen für alle.',imageTag:'Kultur & Diversität',caption:'Sechs Werte. Ein Miteinander.',aboutEye:'KNIEID E.V. · FELLBACH / RAUM STUTTGART',aboutMore:'Kultur, Netzwerk, Integration, Entwicklung, Inspiration und Diversität: Diese sechs Begriffe prägen KNIEID. Wir verbinden gesellschaftliche Teilhabe mit kulturellem Austausch und muslimischem Gemeinschaftsleben – offen für Begegnung und Dialog.',programIntro:'Unsere Themen verbinden die sechs Werte von KNIEID: Kultur, Netzwerk, Integration, Entwicklung, Inspiration und Diversität.',programTitle:'Sechs Werte.<br>Viele Verbindungen.',sixPillars:'KULTUR. NETZWERK.<br>INTEGRATION. ENTWICKLUNG.<br>INSPIRATION. DIVERSITÄT.',eventsEye:'EINBLICKE IN UNSER VEREINSLEBEN',eventsTitle:'Gemeinsam erlebt.<br>Gemeinsam verbunden.',planning:'Vergangene Veranstaltungen',archiveIntro:'Von gemeinsamen Iftar-Abenden bis zum Austausch über Hadsch und Umrah: Einblicke aus der Facebook-Veranstaltungsliste von KNIEID.',eventNote:'Quelle: bereitgestellte Screenshots der Facebook-Seite. Dies sind vergangene Veranstaltungen; es ist keine Anmeldung möglich. Neue Termine werden nach Bestätigung ergänzt.',date:'Vergangen',idea:'Rückblick',contactCopy:'Du hast eine Frage, möchtest mitmachen oder eine Zusammenarbeit anstoßen? Hier erreichst du KNIEID e.V. direkt.',emailUs:'E-Mail schreiben ↗',footerCopy:'Kultur, Netzwerk, Integration, Entwicklung, Inspiration und Diversität. In Fellbach und im Raum Stuttgart.',footerNote:'Fellbach · Raum Stuttgart',prepareMessage:'Nachrichtenentwurf vorbereiten',draftNote:'Lade deinen Entwurf herunter oder öffne ihn anschließend in deinem E-Mail-Programm. Auf dieser Website wird nichts versendet.',sendEmail:'Im E-Mail-Programm öffnen',savedTitle:'Meine gespeicherten Rückblicke'});
Object.assign(copy.en,{brandline:'CULTURE & DIVERSITY · FELLBACH',eyebrow:'ROOTED IN FELLBACH. CONNECTED THROUGH COMMUNITY.',intro:'KNIEID e.V. is the association for promoting culture, networks, integration, development, inspiration and diversity. Based in Fellbach in the Stuttgart area, we create connections with a special focus on Muslim life and a warm welcome for everyone.',imageTag:'Culture & diversity',caption:'Six values. One community.',aboutEye:'KNIEID E.V. · FELLBACH / STUTTGART AREA',aboutMore:'Culture, networks, integration, development, inspiration and diversity: these six ideas shape KNIEID. We connect participation in society with cultural exchange and Muslim community life, welcoming encounters and dialogue.',programIntro:'Our activities connect KNIEID’s six values: culture, networks, integration, development, inspiration and diversity.',programTitle:'Six values.<br>Many connections.',sixPillars:'CULTURE. NETWORKS.<br>INTEGRATION. DEVELOPMENT.<br>INSPIRATION. DIVERSITY.',eventsEye:'A LOOK AT COMMUNITY LIFE',eventsTitle:'Shared experiences.<br>Lasting connections.',planning:'Past events',archiveIntro:'From community iftars to conversations about Hajj and Umrah: a look at KNIEID’s Facebook event history.',eventNote:'Source: supplied screenshots of the Facebook page. These are past events; registration is not available. New dates will be added once confirmed.',date:'Past event',idea:'Looking back',contactCopy:'Have a question, want to get involved or explore a partnership? Contact KNIEID e.V. directly.',emailUs:'Write an email ↗',footerCopy:'Culture, networks, integration, development, inspiration and diversity. In Fellbach and the Stuttgart area.',footerNote:'Fellbach · Stuttgart area',prepareMessage:'Prepare a message draft',draftNote:'Download your draft or open it in your email app afterwards. This website does not send messages.',sendEmail:'Open in email app',savedTitle:'My saved event memories'});
let lang=localStorage.getItem('knieid-language')==='en'?'en':'de',filter=-1;const t=()=>copy[lang],modal=document.getElementById('modal'),content=document.getElementById('modalContent');let bookmarks;try{bookmarks=JSON.parse(localStorage.getItem('knieid-bookmarks')||'[]');if(!Array.isArray(bookmarks))bookmarks=[]}catch{bookmarks=[]}
function render(){document.documentElement.lang=lang;document.querySelectorAll('[data-i]').forEach(e=>e.innerHTML=t()[e.dataset.i]||'');document.getElementById('language').innerHTML=lang==='de'?'DE <span>/ EN</span>':'<span>DE /</span> EN';document.getElementById('menu').ariaLabel=lang==='de'?'Menü öffnen':'Open menu';document.getElementById('closeModal').ariaLabel=t().close;document.getElementById('programGrid').innerHTML=programs.map((p,i)=>`<article class="program-card"><span class="icon">${p.icon}</span><h3>${p[lang][0]}</h3><p>${p[lang][1]}</p><button class="text-link" data-program="${i}">${t().details} <span>↗</span></button></article>`).join('');document.getElementById('valueList').innerHTML=(lang==='de'?['Respekt für jede Geschichte','Offenheit für neue Perspektiven','Teilhabe durch gemeinsames Handeln']:['Respect for every story','Openness to new perspectives','Participation through shared action']).map((s,i)=>`<div><span>0${i+1}</span>${s}</div>`).join('');document.getElementById('filters').innerHTML=[[-1,t().all],...programs.map((p,i)=>[i,p[lang][2]])].map(([i,s])=>`<button data-filter="${i}" class="${i===filter?'active':''}" aria-pressed="${i===filter}">${s}</button>`).join('');renderEvents();const opts=lang==='de'?[['Mitglied werden','Die Gemeinschaft langfristig mitgestalten.'],['Ehrenamtlich mitwirken','Zeit, Wissen und Talente einbringen.'],['Kooperation anfragen','Gemeinsame Ideen und Projekte entwickeln.']]:[['Become a member','Help shape the community over time.'],['Volunteer with us','Contribute your time, knowledge and talents.'],['Explore a partnership','Develop ideas and projects together.']];document.getElementById('joinOptions').innerHTML=opts.map((s,i)=>`<button class="join-option" data-join="${i}"><span>0${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div><span>↗</span></button>`).join('');const faqs=lang==='de'?[['Für wen ist KNIEID da?','Für Menschen, die Kultur, Vernetzung und Integration gemeinsam gestalten möchten. Unser besonderer Fokus liegt auf muslimischen Menschen und Familien. Menschen aller Hintergründe sind willkommen.'],['Wie kann ich Mitglied werden?','Bereite über „Mitglied werden“ einen Interessenentwurf vor. Das offizielle Aufnahmeverfahren, die Satzung und mögliche Beiträge werden nach Bereitstellung durch den Verein ergänzt. Der Entwurf ist kein Mitgliedsantrag.'],['Kann ich mich für die gezeigten Veranstaltungen anmelden?','Die gezeigten Einträge sind vergangene Veranstaltungen aus unserer Facebook-Liste. Aktuelle Ankündigungen findest du auf Facebook oder auf Anfrage per E-Mail.'],['Welche Sprachen nennt die Facebook-Seite?','Deutsch, Englisch, Türkisch, Arabisch, Urdu, Hindi und Bangla. Die Website ist auf Deutsch und Englisch verfügbar.'],['Wie kann ich mich ehrenamtlich einbringen?','Ob Organisation, Sprachbegleitung, Kultur oder Kommunikation: Beschreibe über „Ehrenamtlich mitwirken“, was du beitragen möchtest.'],['Gibt es einen geschützten Mitgliederbereich?','Derzeit gibt es eine Vorschau. Echte Konten und serverseitige Rollen für Mitglieder und Vorstand müssen noch eingerichtet werden.']]:[['Who is KNIEID for?','For people who want to shape culture, networking and integration together. We have a special focus on Muslim people and families, while welcoming people from all backgrounds.'],['How do I become a member?','Use “Become a member” to prepare an expression of interest. The official admissions process, constitution and any fees will be added when supplied by the association. The draft is not a membership application.'],['Can I register for the events shown?','The listed events are past activities from our Facebook event history. For new announcements, visit Facebook or contact us by email.'],['Which languages are listed on the Facebook page?','German, English, Turkish, Arabic, Urdu, Hindi and Bangla. This website is available in German and English.'],['How can I volunteer?','From organisation and language support to culture and communications: use “Volunteer with us” to describe what you would like to contribute.'],['Is there a protected member area?','There is currently a preview. Real accounts and server-side roles for members and the committee still need to be set up.']];document.getElementById('faqList').innerHTML=faqs.map(f=>`<details><summary>${f[0]}</summary><p>${f[1]}</p></details>`).join('');document.title=lang==='de'?'KNIEID e.V. | Gemeinsam mehr verbinden':'KNIEID e.V. | Connecting our community';}
function renderEvents(){const visible=events.map((e,i)=>({...e,i})).filter(e=>filter===-1||e.p===filter);document.getElementById('eventList').innerHTML=visible.length?visible.map(e=>`<article class="event"><div class="event-date"><strong>${e.date[lang].split(" ")[0]}</strong>${e.date[lang].split(" ").slice(1).join(" ")}</div><div><span class="event-cat">${programs[e.p][lang][2]} · ${t().date}</span><h3>${e[lang][0]}</h3><p>${e[lang][1]}</p></div><button class="text-link" data-event="${e.i}">${t().details} ↗</button></article>`).join(''):`<p>${lang==='de'?'Für dieses Thema sind hier noch keine vergangenen Veranstaltungen erfasst.':'No past events have been added for this topic yet.'}</p>`;}
function openModal(html){content.innerHTML=html;modal.showModal()}
function showProgram(i){const p=programs[i];openModal(`<span class="modal-tag">${t().programEye}</span><h2>${p[lang][0]}</h2><p>${p[lang][1]}</p><div class="notice">${lang==='de'?'Dieses Themenfeld beschreibt die inhaltliche Ausrichtung. Konkrete Angebote werden vom Verein bestätigt.':'This area describes the proposed programme direction. Specific activities will be confirmed by the association.'}</div><button class="button primary" id="programInterest">${t().prepareMessage} ↗</button>`);document.getElementById('programInterest').onclick=()=>form(p[lang][0]);}
function showEvent(i){const e=events[i];openModal(`<span class="modal-tag">${t().idea} · ${t().date}</span><h2>${e[lang][0]}</h2><p>${e[lang][1]}</p><div class="notice">${t().eventNote}</div><button class="button primary" id="bookmark">${bookmarks.includes(i)?t().remove:t().save}</button><p class="subtle">${t().portalWarning}</p>`);document.getElementById('bookmark').onclick=()=>{bookmarks=bookmarks.includes(i)?bookmarks.filter(x=>x!==i):[...bookmarks,i];localStorage.setItem('knieid-bookmarks',JSON.stringify(bookmarks));showEventContent(i)};}
function showEventContent(i){modal.close();showEvent(i)}
function portal(role){const member=role==='member';openModal(`<span class="modal-tag">${t().preview}</span><h2>${member?t().memberTitle:t().boardTitle}</h2><div class="notice">${t().portalWarning}</div><div class="dashboard">${(member?[['newsTitle','newsCopy'],['docsTitle','docsCopy']]:[['meetingTitle','meetingCopy'],['tasksTitle','tasksCopy'],['planningTitle','planningCopy'],['accessTitle','accessCopy']]).map(([a,b])=>`<article><h3>${t()[a]}</h3><p>${t()[b]}</p></article>`).join('')}</div>${member?`<h3>${t().savedTitle}</h3>${bookmarks.length?bookmarks.filter(i=>events[i]).map(i=>`<p>${events[i][lang][0]} · ${t().date}</p>`).join(''):`<p>${t().noSaved}</p>`}`:''}`)}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function form(subject=''){openModal(`<span class="modal-tag">${t().contact}</span><h2>${t().prepareMessage}</h2><p>${t().draftNote}</p><form id="messageForm"><label for="person">${t().name}</label><input id="person" name="name" autocomplete="name" required maxlength="150"><label for="email">${t().email}</label><input id="email" name="email" type="email" autocomplete="email" required><label for="subject">${t().interest}</label><input id="subject" name="subject" value="${esc(subject)}" required maxlength="200"><label for="message">${t().message}</label><textarea id="message" name="message" required maxlength="5000"></textarea><button class="button primary" type="submit">${t().draft} ↓</button><p id="formResult" role="status"></p></form>`);document.getElementById('messageForm').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);const body=`KNIEID e.V. — ${t().contact}\n\n${t().name}: ${d.get('name')}\n${t().email}: ${d.get('email')}\n${t().interest}: ${d.get('subject')}\n\n${d.get('message')}`;const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='KNIEID-message-draft.txt';a.click();URL.revokeObjectURL(url);document.getElementById('formResult').className='success';document.getElementById('formResult').textContent=t().downloaded;const link=document.createElement('a');link.className='button primary download';link.textContent=t().sendEmail;link.href='mailto:knieidverein@gmail.com?subject='+encodeURIComponent('KNIEID: '+d.get('subject'))+'&body='+encodeURIComponent(body);document.getElementById('formResult').append(document.createElement('br'),link);};}
function legal(type){const de=lang==='de';openModal(`<span class="modal-tag">${de?'Website-Entwurf':'Website draft'}</span><h2>${type==='imprint'?t().imprint:t().privacy}</h2>${type==='imprint'?`<p>KNIEID e.V.<br>Schaflandstraße 11/1<br>70736 Fellbach, Germany<br>+49 178 2832313<br><a href="mailto:knieidverein@gmail.com">knieidverein@gmail.com</a></p><p>${de?'Angaben aus der bereitgestellten Facebook-Seite. Register- und Vertretungsangaben sind noch zu ergänzen.':'Details from the supplied Facebook page. Registry and representative details still need to be supplied.'}</p><p>${de?'Vollständiger rechtlicher Vereinsname, vertretungsberechtigter Vorstand, Registergericht und Registernummer müssen vom Verein ergänzt und alle Angaben geprüft werden.':'The association must supply its full legal name, authorised representatives, registry court and registration number, and review all details.'}</p>`:`<p>${de?'Diese Vorschau speichert die Sprachwahl und Veranstaltungsvormerkungen lokal in deinem Browser. Nachrichtenentwürfe werden lokal erstellt und nicht an den Verein gesendet.':'This preview stores your language choice and event bookmarks in your browser. Message drafts are generated locally and are not sent to the association.'}</p><p>${de?'Schriften werden von Google Fonts geladen. Dabei können technische Verbindungsdaten an diesen Anbieter übermittelt werden. Das Logo wird lokal vom Hostingdienst geladen. Externe Links zu Facebook, Google Maps und deinem E-Mail-Programm werden erst durch Anklicken geöffnet. Der Hostingdienst verarbeitet technische Zugriffsdaten und stellt die private Anmeldung bereit.':'Fonts are loaded from Google Fonts, which may receive technical connection data. The logo is served by this site. External links to Facebook, Google Maps and your email app are opened only when clicked. The hosting service processes technical access data and provides private site sign-in.'}</p><p>${de?'Eine vollständige Datenschutzerklärung mit Verantwortlichem, Kontaktdaten, Rechtsgrundlagen, Aufbewahrungsfristen und Betroffenenrechten muss vor öffentlichem Betrieb ergänzt werden.':'A complete privacy notice identifying the controller, contact details, legal bases, retention periods and data subject rights must be added before public operation.'}</p><button class="button primary" id="clearLocal">${de?'Lokale Einstellungen löschen':'Clear local settings'}</button>`}`);const clear=document.getElementById('clearLocal');if(clear)clear.onclick=()=>{localStorage.removeItem('knieid-language');localStorage.removeItem('knieid-bookmarks');bookmarks=[];clear.textContent=de?'Gelöscht':'Cleared';};}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.program!==undefined)showProgram(+b.dataset.program);if(b.dataset.filter!==undefined){filter=+b.dataset.filter;render()}if(b.dataset.event!==undefined)showEvent(+b.dataset.event);if(b.dataset.portal)portal(b.dataset.portal);if(b.dataset.join!==undefined)form((lang==='de'?['Mitgliedschaft','Ehrenamt','Kooperation']:['Membership','Volunteering','Partnership'])[+b.dataset.join]);if(b.dataset.legal)legal(b.dataset.legal);});document.getElementById('language').onclick=()=>{lang=lang==='de'?'en':'de';localStorage.setItem('knieid-language',lang);render();};document.getElementById('menu').onclick=()=>{const n=document.getElementById('nav');n.classList.toggle('open');document.getElementById('menu').setAttribute('aria-expanded',n.classList.contains('open'));};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{document.getElementById('nav').classList.remove('open');document.getElementById('menu').setAttribute('aria-expanded','false')});document.getElementById('contactButton').onclick=()=>form();document.getElementById('closeModal').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});document.getElementById('year').textContent=new Date().getFullYear();render();
